// Bakes tools/hub/articles/*.md into tools/hub/src/articles.gen.ts.
//
// Cloudflare Workers have no filesystem, so the markdown cannot be read at
// request time — it is compiled to a plain TS module and bundled. Runs as part
// of `pnpm build`, which runs before both `dev` and `deploy`, so adding an .md
// file is the whole workflow: write it, deploy, done.
//
//   node scripts/build-articles.mjs
//
// The generated file is committed so a fresh clone typechecks without a build.
import { writeFileSync } from "node:fs";
import { readArticles } from "./articles.mjs";

const OUT = new URL("../tools/hub/src/articles.gen.ts", import.meta.url)
  .pathname;

const articles = readArticles();

// `body` is the raw markdown — useful to the tests, dead weight in the bundle.
const shipped = articles.map(({ body, file, ...rest }) => rest);

const banner = `// GENERATED by scripts/build-articles.mjs — do not edit.
//
// Source: tools/hub/articles/*.md. To add an article, add a .md file there and
// run \`pnpm --filter @tools/hub build\` (or just deploy — build runs first).
//
// ${articles.length} article${articles.length === 1 ? "" : "s"}, ${articles.reduce((n, a) => n + a.words, 0)} words.

export type Article = {
  slug: string;
  title: string;
  description: string;
  date: string;
  updated: string;
  tags: string[];
  /** First paragraph as plain text — the citable block and the index blurb. */
  lead: string;
  /** Rendered markdown body. Authored in-repo; there is no user input here. */
  html: string;
  words: number;
  readingMinutes: number;
};

export const ARTICLES: Article[] = ${JSON.stringify(shipped, null, 2)};
`;

writeFileSync(OUT, banner);
console.log(
  `articles: ${articles.length} → src/articles.gen.ts` +
    (articles.length ? ` (${articles.map((a) => a.slug).join(", ")})` : ""),
);
